sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    var d = current.getValue('decision');
    // Only Override and Reject are controlled    
    if (d != 'override' && d != 'reject')
        return;
    // Only check when the decision is being set or changed    
    if (!current.decision.changes())
        return;
    // AC2 + AC4: reason is mandatory for Override and Reject (TC21)    
    if (gs.nil(current.getValue('decision_reason'))) {
        gs.addErrorMessage('A decision reason is mandatory for ' + current.getDisplayValue('decision') + '.');
        current.setAbortAction(true);
        return;
    }
    // AC2: Override only for GST Compliance Approvers    
    if (d == 'override' && !gs.hasRole('admin') && !gs.getUser().isMemberOf('GST Compliance Approvers')) {
        gs.addErrorMessage('Only GST Compliance Approvers can approve an override.');
        current.setAbortAction(true);
    }
})(current, previous);
